-- Small lookup helpers for this file only (dropped at the end).
CREATE FUNCTION seed_uid(p_username TEXT) RETURNS BIGINT LANGUAGE sql STABLE AS $$ SELECT id FROM users WHERE username = p_username $$;
CREATE FUNCTION seed_pid(p_code TEXT) RETURNS BIGINT LANGUAGE sql STABLE AS $$ SELECT id FROM projects WHERE project_code = p_code $$;
CREATE FUNCTION seed_tid(p_code TEXT, p_title TEXT) RETURNS BIGINT LANGUAGE sql STABLE AS $$
    SELECT t.id FROM tasks t JOIN projects p ON p.id = t.project_id WHERE p.project_code = p_code AND t.title = p_title $$;
CREATE FUNCTION seed_mid(p_code TEXT, p_title TEXT) RETURNS BIGINT LANGUAGE sql STABLE AS $$
    SELECT m.id FROM milestones m JOIN projects p ON p.id = m.project_id WHERE p.project_code = p_code AND m.title = p_title $$;

-- A comment, optionally a reply to another comment of the same task (found by its text).
CREATE FUNCTION seed_comment(p_code TEXT, p_task TEXT, p_user TEXT, p_message TEXT, p_at TIMESTAMPTZ, p_parent TEXT)
RETURNS VOID LANGUAGE sql AS $$
    VALUES (seed_tid(p_code, p_task), seed_uid(p_user),
            (SELECT c.id FROM comments c WHERE c.task_id = seed_tid(p_code, p_task) AND c.message = p_parent),
            p_message, p_at, p_at) $$;

-- A small text file on a task (or on the project when p_task is NULL), bytes included.
CREATE FUNCTION seed_attachment(p_code TEXT, p_task TEXT, p_user TEXT, p_name TEXT, p_mime TEXT, p_text TEXT, p_at TIMESTAMPTZ)
RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    VALUES (CASE WHEN p_task IS NULL THEN seed_pid(p_code) END,
            CASE WHEN p_task IS NOT NULL THEN seed_tid(p_code, p_task) END,
            seed_uid(p_user), p_name, octet_length(convert_to(p_text, 'UTF8')), p_mime, p_at)
    RETURNING id INTO v_id;
END $$;


