-- ==================== approvals ====================

-- A task in review has one open (PENDING) request; every completed task has an APPROVED record, and
-- a few were sent back for changes first.



-- ==================== system roles for the seeded users ====================
-- The same rule as migration V10: anyone who owns a project is a PROJECT_MANAGER, everyone else a USER;
-- admin.system is the ADMINISTRATOR (set above). Authority inside a project comes from project_members.
UPDATE users u
SET role_id = (SELECT id FROM roles WHERE name = 'PROJECT_MANAGER')
WHERE u.role_id IS NULL
  AND EXISTS (SELECT 1 FROM project_members pm
              WHERE pm.user_id = u.id AND pm.status = 'ACTIVE' AND pm.project_role = 'OWNER');

UPDATE users SET role_id = (SELECT id FROM roles WHERE name = 'USER') WHERE role_id IS NULL;

-- A few people prefer the dark theme.
UPDATE users SET theme_preference = 'DARK' WHERE username IN ('dev.chen', 'dev.hana', 'qa.zoe', 'design.kai');

